  (function(){var d=document.documentElement;function g(k,v){try{return localStorage.getItem(k)||v}catch(e){return v}}
  function q(s){return !!(window.matchMedia&&window.matchMedia(s).matches)}
  var t=g('c64Theme','c64');var m=t==='paper'?'light':(t==='auto'?(q('(prefers-color-scheme: light)')?'light':'dark'):'dark');
