head.b:skin:
/* ===========================================================
   COMMODORE 64 THEME v2.11 — Blogger theme for type-in BASIC listings
   Colors: Theme > Customize > Advanced
   =========================================================== */

/*
<Group description="C64 screen" selector="body">
  <Variable name="border.color" description="C64 border (page edge)" type="color" default="#706deb" value="#706deb"/>
  <Variable name="screen.color" description="C64 screen" type="color" default="#2e2c9b" value="#2e2c9b"/>
  <Variable name="surface.color" description="Panels" type="color" default="#26248a" value="#26248a"/>
  <Variable name="text.color" description="Body text" type="color" default="#cfcdff" value="#cfcdff"/>
  <Variable name="muted.color" description="Secondary text" type="color" default="#9f9cff" value="#9f9cff"/>
  <Variable name="rule.color" description="Frames and rules" type="color" default="#706deb" value="#706deb"/>
</Group>

<Group description="C64 accents" selector="body">
  <Variable name="heading.color" description="Headings" type="color" default="#edf171" value="#edf171"/>
  <Variable name="link.color" description="Links" type="color" default="#75cec8" value="#75cec8"/>
  <Variable name="link.hover.color" description="Links on hover" type="color" default="#a9ff9f" value="#a9ff9f"/>
  <Variable name="accent.color" description="Errors and errata" type="color" default="#ff8a8a" value="#ff8a8a"/>
</Group>

<Group description="C64 listings" selector="body">
  <Variable name="listing.text.color" description="Listing text" type="color" default="#a7a4ff" value="#a7a4ff"/>
  <Variable name="keyword.color" description="BASIC keywords" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="linenum.color" description="Line numbers" type="color" default="#edf171" value="#edf171"/>
  <Variable name="string.color" description="Strings" type="color" default="#a9ff9f" value="#a9ff9f"/>
  <Variable name="comment.color" description="REM comments" type="color" default="#b2b2b2" value="#b2b2b2"/>
</Group>
*/

:root{
  --border:$(border.color);
  --screen:$(screen.color);
  --surface:$(surface.color);
  --text:$(text.color);
  --muted:$(muted.color);
  --rule:$(rule.color);
  --heading:$(heading.color);
  --link:$(link.color);
  --link-hover:$(link.hover.color);
  --accent:$(accent.color);
  --l-text:$(listing.text.color);
  --l-kw:$(keyword.color);
  --l-num:$(linenum.color);
  --l-str:$(string.color);
  --l-rem:$(comment.color);
  --l-bg:#2e2c9b;
  --status-bg:#706deb;
  --status-text:#2e2c9b;
  --c0:#000000;--c1:#ffffff;--c2:#813338;--c3:#75cec8;--c4:#8e3c97;--c5:#56ac4d;--c6:#2e2c9b;--c7:#edf171;
  --c8:#8e5029;--c9:#553800;--c10:#c46c71;--c11:#4a4a4a;--c12:#7b7b7b;--c13:#a9ff9f;--c14:#706deb;--c15:#b2b2b2;
  --font-pixel:'Press Start 2P',monospace;
  --font-ui:'VT323',monospace;
  --font-mono:'IBM Plex Mono',Consolas,monospace;
  --font-body:'IBM Plex Sans',system-ui,-apple-system,'Segoe UI',sans-serif;
  --frame:clamp(10px,3vw,40px);
}

/* ---------- Base ---------- */
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-padding-top:60px}
body{margin:0;background:var(--border);color:var(--text);font-family:var(--font-body);font-size:17px;line-height:1.7}
a{color:var(--link)}
a:hover{color:var(--link-hover)}
:focus-visible{outline:3px solid var(--heading);outline-offset:2px}
::selection{background:#706deb;color:#fff}
img{max-width:100%;height:auto}
.cursor{display:inline-block;width:1ch;height:1em;line-height:1;vertical-align:-.1em;overflow:hidden;color:transparent;background:currentColor;animation:c64blink 1.06s steps(1) infinite}
@keyframes c64blink{50%{opacity:0}}

/* ---------- Tape loading stripes on the border ---------- */
body::before{content:'';position:fixed;top:0;right:0;bottom:0;left:0;z-index:0;pointer-events:none;opacity:0;
  background:repeating-linear-gradient(to bottom,#706deb 0 7px,#edf171 7px 11px,#2e2c9b 11px 19px,#a9ff9f 19px 22px,#813338 22px 29px,#75cec8 29px 33px,#8e3c97 33px 41px,#ffffff 41px 43px,#8e5029 43px 50px,#000000 50px 53px);
  background-size:100% 53px}
html.tape body::before{opacity:1;animation:c64tape .6s steps(7) infinite}
@keyframes c64tape{to{background-position:0 -371px}}

/* ---------- Frame + screen ---------- */
.c64-frame{position:relative;z-index:1;padding:var(--frame)}
.c64-screenarea{position:relative;max-width:1280px;margin:0 auto;background:var(--screen);box-shadow:inset 0 0 90px rgba(0,0,0,.35)}
.c64-screenarea::after{content:'';position:absolute;top:0;right:0;bottom:0;left:0;z-index:60;pointer-events:none;
  background:repeating-linear-gradient(to bottom,transparent 0 2px,rgba(0,0,0,.12) 2px 3px)}
html[data-crt="off"] .c64-screenarea::after,html[data-mode="light"] .c64-screenarea::after{display:none}

/* ---------- Status bar ---------- */
.status-bar{position:sticky;top:0;z-index:70;display:flex;align-items:center;justify-content:space-between;gap:14px;
  background:var(--status-bg);color:var(--status-text);font-family:var(--font-ui);font-size:22px;line-height:1;padding:7px 16px;text-transform:uppercase}
.sb-left{display:flex;align-items:center;gap:12px;min-width:0;white-space:nowrap}
.sb-state{overflow:hidden;text-overflow:ellipsis}
.sb-counter{display:none;padding:2px 6px 1px;background:var(--status-text);color:var(--status-bg);letter-spacing:.12em}
body.is-item .sb-counter{display:inline-block}
.sb-title{flex:1;min-width:0;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;opacity:.75}
.sb-btns{display:flex;gap:14px;flex:none}
.sb-btn{background:none;border:0;padding:0;font:inherit;color:inherit;cursor:pointer;white-space:nowrap;text-transform:uppercase}
.sb-btn:hover .val{background:var(--status-text);color:var(--status-bg)}
@media (max-width:760px){.sb-title{display:none}.status-bar{font-size:19px;gap:10px;padding:6px 10px}.sb-btns{gap:10px}}
@media (max-width:480px){.sb-btn .lbl{display:none}body.is-item .sb-state{display:none}}

/* ---------- Header ---------- */
.site-header{position:relative;padding:28px clamp(16px,4vw,48px) 34px}
.boot{margin:0 0 18px;max-height:320px;font-family:var(--font-pixel);font-size:clamp(7px,1.25vw,11px);line-height:1.75;color:var(--l-text);white-space:pre;overflow:hidden;transition:max-height .7s ease,opacity .5s ease,margin .7s ease}
.boot.done{max-height:0;opacity:0;margin:0}
html:not(.first-boot) .boot{display:none}
.site-header .widget{margin:0}
.site-header h1,.site-header h2{margin:0;font-family:var(--font-pixel);font-weight:normal;font-size:clamp(19px,4.4vw,46px);line-height:1.4;color:var(--heading)}
body.is-item .site-header h1,body.is-item .site-header h2{font-size:clamp(16px,3vw,30px)}
.site-header h1 a,.site-header h2 a{color:inherit;text-decoration:none}
html[data-mode="dark"] .site-header h1,html[data-mode="dark"] .site-header h2{
  background:repeating-linear-gradient(to bottom,#edf171 0 .125em,#a9ff9f .125em .25em,#75cec8 .25em .375em,#ffffff .375em .5em,#75cec8 .5em .625em,#a9ff9f .625em .75em,#edf171 .75em .875em,#c46c71 .875em 1em);
  -webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(4px 4px 0 rgba(0,0,0,.55));animation:c64raster 2.4s steps(8) infinite}
@keyframes c64raster{to{background-position:0 1em}}
.site-header p{margin:16px 0 0;max-width:820px;font-family:var(--font-ui);font-size:24px;line-height:1.2;color:var(--muted)}

/* ---------- Menu ---------- */
.menu-bar{border-top:3px solid var(--rule);border-bottom:3px solid var(--rule)}
.menu{padding:0 clamp(8px,3vw,40px);display:flex;flex-wrap:wrap;align-items:stretch;gap:0 8px}
.menu .widget{margin:0}
.menu .PageList .title{display:none}
.menu ul{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap}
.menu li{margin:0;padding:0}
.menu li a{display:block;padding:9px 14px;font-family:var(--font-ui);font-size:22px;line-height:1.2;color:var(--text);text-decoration:none;text-transform:uppercase}
.menu li a:hover,.menu li.selected a{background:var(--text);color:var(--screen)}
.menu .LinkList{position:relative;margin-left:auto}
.menu .LinkList .title{margin:0;padding:9px 14px;font-family:var(--font-ui);font-size:22px;line-height:1.2;font-weight:normal;color:var(--link);cursor:pointer;text-transform:uppercase}
.menu .LinkList .widget-content{display:none;position:absolute;right:0;top:100%;z-index:40;min-width:250px;background:#2e2c9b;border:3px solid #706deb}
.menu .LinkList:hover .widget-content,.menu .LinkList.open .widget-content{display:block}
.menu .LinkList ul{flex-direction:column}
.menu .LinkList li a{color:#a7a4ff}
.menu .LinkList li a:hover{background:#a7a4ff;color:#2e2c9b}

/* ---------- Layout ---------- */
.layout{padding:32px clamp(12px,3vw,40px);display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:32px}
@media (max-width:900px){.layout{grid-template-columns:minmax(0,1fr)}}
.main-col,.sidebar{min-width:0}
@media (min-width:901px){.sidebar{position:sticky;top:50px;align-self:start}}

/* ---------- Posts ---------- */
.blog-posts{margin:0}
.post-outer-container{background:var(--surface);border:3px solid var(--rule);padding:28px clamp(16px,3.5vw,44px);margin:0 0 32px;box-shadow:8px 8px 0 rgba(0,0,0,.3)}
.post-title{margin:0 0 12px;font-family:var(--font-pixel);font-weight:normal;font-size:clamp(14px,2.2vw,21px);line-height:1.6;color:var(--heading)}
.post-title a{color:inherit;text-decoration:none}
.post-title a:hover{color:var(--link)}
.post-header,.post-footer,.byline,.post-labels{font-family:var(--font-ui);font-size:20px;line-height:1.3;color:var(--muted)}
.post-header{margin-bottom:20px}
.post-footer{margin-top:28px;padding-top:12px;border-top:2px dashed var(--rule)}
.byline{margin-right:12px}
.byline a,.post-labels a{color:var(--link)}
.post-header .post-share-buttons{display:none}
.post-header svg,.byline svg{width:16px;height:16px;fill:var(--muted);vertical-align:-2px}

.post-body{font-size:17px;line-height:1.75;color:var(--text);overflow-wrap:break-word}
.post-body p{margin:0 0 1.1em}
.post-body h2{margin:2.2em 0 .9em;padding:8px 12px 6px;background:var(--rule);color:#fff;font-family:var(--font-pixel);font-weight:normal;font-size:14px;line-height:1.6}
.post-body h3{margin:1.6em 0 .4em;font-family:var(--font-ui);font-weight:normal;font-size:28px;line-height:1.15;color:var(--heading);text-transform:uppercase}
.post-body h4{margin:1.4em 0 .3em;font-size:17px;font-weight:600;color:var(--link)}
.post-body ul,.post-body ol{padding-left:1.4em}
.post-body li{margin:.25em 0}
.post-body blockquote{margin:1.5em 0;padding:4px 0 4px 18px;border-left:4px solid var(--muted);color:var(--muted);font-style:italic}
.post-body hr{border:0;height:6px;margin:2.2em 0;background:repeating-linear-gradient(90deg,var(--rule) 0 6px,transparent 6px 12px)}
.post-body iframe{max-width:100%}
.post-body .separator a{margin:0 !important}
.post-body img.c64-shot{display:block;width:100%;max-width:768px;height:auto;margin:0 auto;image-rendering:pixelated;border:3px solid var(--rule)}
.post-body .tr-caption-container{margin:1.5em auto;border:0}
.post-body .tr-caption{font-family:var(--font-ui);font-size:19px;line-height:1.2;color:var(--muted);text-align:center;padding-top:6px}
.post-body table{border-collapse:collapse}
.post-body table.data{width:100%;margin:1.5em 0;font-size:15px}
.post-body table.data th{font-family:var(--font-ui);font-size:20px;font-weight:normal;text-align:left;color:var(--heading);border-bottom:3px solid var(--rule);padding:6px 10px}
.post-body table.data td{border-bottom:1px solid var(--rule);padding:6px 10px;vertical-align:top}
.table-wrap{overflow-x:auto}

/* Inline code, typed commands, keys */
.post-body code{font-family:var(--font-mono);font-size:.9em;padding:1px 6px;background:var(--screen);border:1px solid var(--rule)}
.post-body .cmd{display:inline-block;padding:3px 7px;font-family:var(--font-pixel);font-size:11px;line-height:1.5;background:#2e2c9b;color:#a7a4ff;text-transform:uppercase;vertical-align:1px}
.post-body kbd{display:inline-block;min-width:2em;padding:2px 8px 5px;font-family:var(--font-mono);font-size:12px;font-weight:600;line-height:1.25;text-align:center;text-transform:uppercase;
  color:#efe6d6;background:linear-gradient(#5d493a,#3b2d23);border:1px solid #1a120d;border-radius:4px;
  box-shadow:inset 0 -4px 0 #261b14,0 2px 0 rgba(0,0,0,.45);vertical-align:2px;white-space:nowrap}
.post-body kbd.fn{color:#2b2118;background:linear-gradient(#e2cfa6,#bca172);border-color:#6d5b3e;box-shadow:inset 0 -4px 0 #94794d,0 2px 0 rgba(0,0,0,.45)}

/* ---------- Listing box ---------- */
.listing-wrap{margin:1.8em 0;border:3px solid #706deb;background:var(--l-bg);box-shadow:8px 8px 0 rgba(0,0,0,.4)}
.listing-bar{display:flex;flex-wrap:wrap;align-items:center;gap:6px 14px;padding:6px 8px 6px 12px;background:#706deb;color:#2e2c9b;font-family:var(--font-ui);font-size:20px;line-height:1.1;text-transform:uppercase}
.listing-name{font-family:var(--font-pixel);font-size:11px;line-height:1.6}
.listing-typed{padding:1px 6px;background:#2e2c9b;color:#a9ff9f}
.listing-warn{padding:1px 6px;background:#813338;color:#fff;cursor:help}
.listing-actions{margin-left:auto;display:flex;flex-wrap:wrap;gap:6px}
.listing-actions button{font-family:var(--font-ui);font-size:19px;line-height:1;padding:5px 9px 4px;background:#2e2c9b;color:#a7a4ff;border:0;cursor:pointer;text-transform:uppercase}
.listing-actions button:hover{background:#fff;color:#2e2c9b}
.listing-screen{position:relative;overflow-x:auto;padding:16px 0;background:var(--l-bg)}
pre.listing-code{margin:0;padding:0 18px 0 0;min-width:max-content;font-family:var(--font-pixel);font-size:13px;line-height:24px;color:var(--l-text);white-space:pre;background:none;border:0}
html[data-font="mono"] pre.listing-code{font-family:var(--font-mono);font-size:15px}
.listing-code .line{display:block;position:relative;min-height:24px;padding-left:32px;cursor:pointer}
.listing-code .line:hover{background:rgba(255,255,255,.07)}
.listing-code .line.note{cursor:default;color:var(--l-rem)}
.listing-code .line.done{opacity:.33}
.listing-code .line.done::before{content:'\2713';position:absolute;left:10px;font-family:var(--font-mono);color:var(--l-str)}
.listing-code .lnum{color:var(--l-num)}
.listing-code .kw{color:var(--l-kw)}
.listing-code .str{color:var(--l-str)}
.listing-code .rem{color:var(--l-rem)}
.listing-code .dat{color:#75cec8}
.pc{display:inline-block;padding:0 .28em;margin:0 .06em;background:var(--l-text);color:#2e2c9b;line-height:1.35;cursor:help}
.pc-col{background:var(--pc);color:#000;box-shadow:inset 0 0 0 1px rgba(255,255,255,.55)}
.pc-col.pc-dark{color:#fff}
.listing-legend{border-top:2px dashed #706deb;padding:8px 14px 12px;font-family:var(--font-ui);font-size:20px;line-height:1.25;color:var(--l-text);background:var(--l-bg)}
.listing-legend summary{cursor:pointer;color:#edf171;text-transform:uppercase}
.listing-legend dl{display:grid;grid-template-columns:auto 1fr;gap:6px 14px;margin:10px 0 0}
.listing-legend dt{font-family:var(--font-pixel);font-size:10px}
.listing-legend dd{margin:0}

/* Program output:  <div class="c64-screen"><pre>HELLO</pre></div> */
.c64-screen{max-width:640px;margin:1.6em auto;padding:clamp(14px,3vw,30px);background:#706deb;box-shadow:8px 8px 0 rgba(0,0,0,.4)}
.c64-screen pre,.c64-screen p{display:block;margin:0;padding:14px 16px;background:#2e2c9b;color:#a7a4ff;font-family:var(--font-pixel);font-size:clamp(8px,1.6vw,13px);line-height:1.9;white-space:pre-wrap;text-transform:uppercase;min-height:120px}

/* Info box */
.book-card,.info-card{margin:0 0 1.8em;padding:18px 22px;background:var(--screen);border:3px solid var(--rule);box-shadow:6px 6px 0 rgba(0,0,0,.3)}
.book-card-title,.info-card-title{margin:0 0 12px !important;font-family:var(--font-pixel);font-size:12px;line-height:1.7;color:var(--heading)}
.book-card dl,.info-card dl{display:grid;grid-template-columns:auto 1fr;gap:4px 16px;margin:0}
.book-card dt,.info-card dt{font-family:var(--font-ui);font-size:20px;line-height:1.3;color:var(--muted);text-transform:uppercase}
.book-card dd,.info-card dd{margin:0;font-family:var(--font-ui);font-size:21px;line-height:1.3;color:var(--text)}
.info-card-status{margin:14px 0 0;padding-top:10px;border-top:2px dashed var(--rule);font-family:var(--font-ui);font-size:21px;color:#a9ff9f}

/* Callouts */
.tip,.warn,.errata{margin:1.6em 0;padding:12px 18px}
.tip{border-left:6px solid var(--link);background:rgba(117,206,200,.1)}
.warn{border-left:6px solid var(--heading);background:rgba(237,241,113,.09)}
.errata{border-left:6px solid var(--accent);background:rgba(255,138,138,.1)}
.tip::before,.warn::before,.errata::before{display:block;font-family:var(--font-pixel);font-size:10px;line-height:1.6;margin-bottom:6px}
.tip::before{content:'TIP';color:var(--link)}
.warn::before{content:'?CAREFUL  ERROR';color:var(--heading)}
.errata::before{content:'?MISPRINT  ERROR';color:var(--accent)}
.tip p:last-child,.warn p:last-child,.errata p:last-child{margin-bottom:0}

/* Table of contents */
.toc{margin:0 0 2em;padding:14px 20px;background:var(--screen);border:3px solid var(--rule)}
.toc-title{margin:0 0 8px !important;font-family:var(--font-pixel);font-size:11px;line-height:1.6;color:var(--heading)}
.post-body .toc ul{list-style:none;margin:0;padding:0;font-family:var(--font-ui);font-size:21px;line-height:1.3}
.toc li{margin:2px 0}
.toc li a{text-decoration:none}
.toc li::before{content:'\25B8 ';color:var(--muted)}
.toc li.lvl3{margin-left:1.3em}

/* Ads */
.ad-inline{margin:2em 0;text-align:center}
.ad-section .widget{margin:0 0 24px;text-align:center}
.ad-section .widget > .title{display:none}
.sidebar .ad-section .widget{padding:0;background:none;border:0}

/* Lists, pager */
.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
.jump-link{margin-top:16px}
.jump-link a,.blog-pager a,.btn{display:inline-block;padding:5px 14px 4px;font-family:var(--font-ui);font-size:22px;line-height:1.2;text-transform:uppercase;
  background:var(--text);color:var(--screen);text-decoration:none;border:0;cursor:pointer}
.jump-link a:hover,.blog-pager a:hover,.btn:hover{background:var(--heading);color:#000}
.blog-pager{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;margin:24px 0;padding:0}
.blog-feeds{display:none}

/* Comments */
.comments{margin-top:32px;padding-top:16px;border-top:3px solid var(--rule)}
.comments h3,.comments .title{font-family:var(--font-pixel);font-weight:normal;font-size:12px;line-height:1.6;color:var(--heading)}
.comments .user,.comments .user a{font-weight:600;color:var(--link)}
.comments .datetime,.comments .datetime a{font-size:13px;color:var(--muted)}

/* Sidebar */
.sidebar .widget{margin:0 0 24px;padding:16px 18px;background:var(--surface);border:3px solid var(--rule)}
.sidebar .widget > .title,.sidebar h3.title{margin:-16px -18px 14px;padding:8px 12px 6px;background:var(--rule);color:#fff;font-family:var(--font-pixel);font-weight:normal;font-size:11px;line-height:1.6}
.sidebar ul{list-style:none;margin:0;padding:0}
.sidebar li{margin:0;padding:3px 0;font-family:var(--font-ui);font-size:21px;line-height:1.25}
.sidebar li a{text-decoration:none}
.sidebar .Label li a::before{content:'\25B8 ';color:var(--muted)}
.sidebar .label-count{color:var(--muted);margin-left:4px}
/* Compact "Most typed": title + small thumbnail only */
.sidebar .PopularPosts .post-header,.sidebar .PopularPosts .byline,.sidebar .PopularPosts time,.sidebar .PopularPosts .post-timestamp,
.sidebar .PopularPosts .timestamp-link,.sidebar .PopularPosts .snippet-container,.sidebar .PopularPosts .snippet-item,
.sidebar .PopularPosts .post-snippet,.sidebar .PopularPosts .item-snippet,.sidebar .PopularPosts .snippet-fade,
.sidebar .PopularPosts .post-share-buttons,.sidebar .PopularPosts .jump-link{display:none !important}
.sidebar .PopularPosts article,.sidebar .PopularPosts .post,.sidebar .PopularPosts li{display:flow-root;margin:0 0 10px !important;padding:0 0 10px;border-bottom:1px dashed var(--rule)}
.sidebar .PopularPosts article:last-child,.sidebar .PopularPosts .post:last-child,.sidebar .PopularPosts li:last-child{border-bottom:0;margin-bottom:0 !important;padding-bottom:0}
.sidebar .PopularPosts .post-content{display:flex;align-items:center;gap:10px}
.sidebar .PopularPosts .snippet-thumbnail,.sidebar .PopularPosts .item-thumbnail{order:-1;flex:none;margin:0 !important}
.sidebar .PopularPosts .container:not(.snippet-thumbnail){display:none}
.sidebar .PopularPosts img{display:block;width:64px !important;height:48px !important;margin:0 !important;object-fit:cover;border:1px solid var(--rule)}
.sidebar .PopularPosts .post-content-link{flex:1;min-width:0;text-decoration:none}
.sidebar .PopularPosts .post-title,.sidebar .PopularPosts .item-title{margin:0 !important;padding:0;font-family:var(--font-ui);font-size:20px;font-weight:normal;line-height:1.1;color:var(--link)}
.sidebar .PopularPosts .post-title a,.sidebar .PopularPosts .item-title a{color:var(--link);text-decoration:none}
/* Labels: disks first, with a disk mark */
.sidebar .Label li.is-book a::before{content:'\25A4 ';color:var(--heading)}
.sidebar .Label li.is-book + li:not(.is-book){margin-top:8px;padding-top:9px;border-top:1px dashed var(--rule)}
.Profile .profile-name-link,.Profile .profile-link{font-family:var(--font-ui);font-size:21px}
.Profile .profile-textblock{font-size:15px;line-height:1.6}
.BlogSearch form{display:flex;gap:8px}
.BlogSearch input[type=text],.BlogSearch .search-input input{flex:1;min-width:0;width:100%;padding:4px 8px;background:var(--screen);color:var(--text);border:2px solid var(--muted);border-radius:0;font-family:var(--font-ui);font-size:20px}
.BlogSearch input[type=submit],.BlogSearch .search-action{padding:4px 12px;background:var(--text);color:var(--screen);border:0;border-radius:0;font-family:var(--font-ui);font-size:20px;cursor:pointer}

/* Error page */
.error-screen{max-width:680px;margin:0 auto 32px;padding:22px 24px;background:#2e2c9b;border:3px solid #706deb;font-family:var(--font-pixel);font-size:clamp(9px,1.6vw,13px);line-height:2;color:#a7a4ff}
.error-screen p{margin:0}
.error-screen .err{color:#fff}
.error-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:20px}

/* Footer */
.site-footer{padding:32px clamp(16px,4vw,48px) 44px;border-top:3px solid var(--rule)}
.site-footer .ready{margin:0 0 14px;font-family:var(--font-pixel);font-size:13px;line-height:1.8;color:var(--l-text)}
.site-footer .fineprint{max-width:680px;margin:0 0 12px;font-size:13px;line-height:1.6;color:var(--muted)}
.Attribution{font-size:12px;color:var(--muted)}
.Attribution a{color:var(--muted)}
.Attribution svg{width:16px;height:16px;fill:currentColor;vertical-align:middle}
.to-top{position:fixed;right:18px;bottom:18px;z-index:80;padding:10px 12px 8px;font-family:var(--font-pixel);font-size:11px;line-height:1;color:#2e2c9b;background:#a7a4ff;border:0;box-shadow:4px 4px 0 rgba(0,0,0,.5);cursor:pointer;opacity:0;visibility:hidden}
.to-top.show{opacity:1;visibility:visible}
.to-top:hover{background:#fff}

/* Build pipeline:  <ol class="pipeline"><li><b>Step</b><span>text</span></li>...</ol> */
.post-body ol.pipeline{list-style:none;counter-reset:step;display:flex;flex-direction:column;gap:26px;margin:1.8em 0;padding:0}
.post-body ol.pipeline li{counter-increment:step;position:relative;display:grid;grid-template-columns:auto 1fr;gap:2px 14px;align-items:center;margin:0;padding:12px 16px;
  background:#2e2c9b;border:3px solid #706deb;color:#a7a4ff;box-shadow:5px 5px 0 rgba(0,0,0,.35)}
.post-body ol.pipeline li::before{content:counter(step);grid-row:span 2;font-family:var(--font-pixel);font-size:16px;color:#edf171}
.post-body ol.pipeline li:not(:last-child)::after{content:'\25BC';position:absolute;left:50%;bottom:-25px;transform:translateX(-50%);font-size:15px;line-height:1;color:var(--heading)}
.post-body ol.pipeline b{font-family:var(--font-ui);font-size:25px;font-weight:normal;line-height:1.05;color:#fff;text-transform:uppercase}
.post-body ol.pipeline span{font-size:14px;line-height:1.45}
@media (min-width:1180px){
  .post-body ol.pipeline{flex-direction:row;gap:26px}
  .post-body ol.pipeline li{flex:1 1 0;min-width:0;display:block;padding:12px 12px 14px}
  .post-body ol.pipeline li::before{display:block;margin-bottom:8px;font-size:11px}
  .post-body ol.pipeline b{display:block;margin-bottom:4px;font-size:23px;overflow-wrap:anywhere}
  .post-body ol.pipeline span{display:block;font-size:13px}
  .post-body ol.pipeline li:not(:last-child)::after{content:'\25B6';left:auto;right:-21px;top:50%;bottom:auto;transform:translateY(-50%)}
}
/* Shell / file tree block:  <pre class="code">...</pre> */
.post-body pre.code{margin:1.5em 0;padding:14px 16px;overflow-x:auto;background:#1d1c6b;color:#cfcdff;border-left:6px solid var(--rule);font-family:var(--font-mono);font-size:14px;line-height:1.6;white-space:pre}
.post-body pre.code .dim{color:#8a87e0}

/* Official brand icons (GitHub mark: @primer/octicons; YouTube: simple-icons, official colours) */
.brand-ico{display:inline-block;width:1.1em;height:1.1em;vertical-align:-.17em;background:center/contain no-repeat}
