.follow-link.support{border-color:#FF6433}
.hub-welcome .hub-follow .follow-link.support{border-color:#FF6433}
.follow{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center}
.follow-link{display:inline-flex;align-items:center;gap:8px;padding:5px 12px 4px;font-family:var(--font-ui);font-size:21px;line-height:1.1;text-transform:uppercase;text-decoration:none;color:var(--text);border:2px solid var(--rule)}
.follow-link:hover{color:var(--text);border-color:var(--text);background:rgba(255,255,255,.06)}
.hub-welcome .hub-follow{margin:16px 0 0;padding-top:14px;border-top:2px dashed #5a57c8}
.hub-follow .follow-link{color:#a7a4ff;border-color:#5a57c8}
.hub-follow .follow-link:hover{color:#fff;border-color:#a7a4ff}
.site-footer .follow{margin:0 0 18px}

/* ---------- Home hub ---------- */
.hub{display:none}
body.is-home .hub{display:block}
body.is-home .layout{grid-template-columns:minmax(0,1fr)}
body.is-home .sidebar{display:none}
html.js body.is-home #main{display:none}
html.js body.is-home.hub-failed #main{display:block}
.hub-loading{font-family:var(--font-ui);font-size:22px;color:var(--muted)}
.hub-hero{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:28px;margin:0 0 48px;align-items:stretch}
.hub-hero.solo{grid-template-columns:minmax(0,1fr)}
@media (max-width:900px){.hub-hero{grid-template-columns:minmax(0,1fr)}}
.hub-welcome{background:#2e2c9b;color:#a7a4ff;border:3px solid #706deb;padding:24px 28px;box-shadow:8px 8px 0 rgba(0,0,0,.4)}
.hub-welcome h2{margin:0 0 16px;font-family:var(--font-pixel);font-weight:normal;font-size:clamp(13px,1.7vw,17px);line-height:1.6;color:#edf171}
.hub-welcome p{margin:0 0 18px;font-family:var(--font-ui);font-size:25px;line-height:1.25}
.hub-actions{display:flex;flex-wrap:wrap;gap:10px;margin:0 0 20px}
.hub-btn{display:inline-block;padding:6px 16px 5px;font-family:var(--font-ui);font-size:23px;line-height:1.2;text-decoration:none;text-transform:uppercase;background:#a7a4ff;color:#2e2c9b;border:2px solid #a7a4ff}
.hub-btn:hover{background:#fff;border-color:#fff;color:#2e2c9b}
.hub-btn.alt{background:transparent;color:#a7a4ff}
.hub-btn.alt:hover{background:#a7a4ff;color:#2e2c9b}
.hub-search{display:flex;align-items:center;padding-top:16px;border-top:2px dashed #5a57c8;font-family:var(--font-pixel);font-size:clamp(10px,1.4vw,14px);line-height:1.6;color:#fff}
.hub-search label,.hub-search span{flex:none}
.hub-search input{flex:1;min-width:0;padding:2px;background:transparent;color:#fff;border:0;border-bottom:2px solid #a7a4ff;border-radius:0;font:inherit;text-transform:uppercase;outline:none}
.hub-search input::placeholder{color:#7d7ad6}
.hub-latest{margin:14px 0 0 !important;font-size:20px !important}
.hub-latest a{color:#edf171}
.hub-info .widget{margin:0;height:100%}
.hub-info .widget > .title{display:none}
.hub-info .info-card{height:100%;margin:0}
.hub-title{display:flex;align-items:baseline;justify-content:space-between;flex-wrap:wrap;gap:6px 12px;margin:0 0 18px;padding-bottom:8px;border-bottom:3px solid var(--rule)}
.hub-title h2{margin:0;font-family:var(--font-pixel);font-weight:normal;font-size:15px;line-height:1.6;color:var(--heading)}
.hub-title span{font-family:var(--font-ui);font-size:20px;color:var(--muted);text-transform:uppercase}

/* Disk directory */
.dir-filters{display:flex;flex-direction:column;gap:10px;margin:0 0 14px}
.dir-filter-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px}
.dir-lbl{min-width:3.6em;font-family:var(--font-ui);font-size:18px;line-height:1;color:var(--muted)}
.dir-search{display:flex;align-items:center;max-width:520px;font-family:var(--font-pixel);font-size:12px;line-height:1.6;color:var(--text);cursor:text}
.dir-search span{flex:none}
.dir-search input{flex:1;min-width:0;padding:2px;background:transparent;color:var(--heading);border:0;border-bottom:2px solid var(--rule);border-radius:0;font:inherit;text-transform:uppercase;outline:none;caret-color:var(--heading)}
.dir-search input:focus{border-bottom-color:var(--heading)}
.dir-search input::placeholder{color:var(--muted);opacity:.6}
@media (max-width:700px){
  .dir-filter-row{flex-wrap:nowrap;overflow-x:auto;scrollbar-width:none;-webkit-overflow-scrolling:touch;padding-bottom:2px}
  .dir-filter-row::-webkit-scrollbar{display:none}
  .dir-filter-row button,.dir-lbl{flex:none;white-space:nowrap}
}
.dir-filters button{padding:4px 10px 3px;font-family:var(--font-ui);font-size:20px;line-height:1.1;text-transform:uppercase;background:transparent;color:var(--text);border:2px solid var(--rule);cursor:pointer}
.dir-filters button.on{background:var(--text);color:var(--screen);border-color:var(--text)}
.dir{margin:0 0 52px;padding:18px clamp(10px,2.4vw,24px);background:#2e2c9b;color:#a7a4ff;border:3px solid #706deb;box-shadow:8px 8px 0 rgba(0,0,0,.4);font-family:var(--font-pixel);font-size:clamp(8px,1.15vw,13px);line-height:2.1;text-transform:uppercase}
.dir p{margin:0}
.dir-head{display:inline-block;margin:6px 0 4px;padding:0 .2em;background:#a7a4ff;color:#2e2c9b;white-space:pre}
.dir-row{display:grid;grid-template-columns:5ch minmax(0,1fr) 4ch;gap:0 1ch;padding:1px 4px;color:inherit;text-decoration:none}
.dir-row:hover{background:#a7a4ff;color:#2e2c9b}
.dir-blk{text-align:right}
.dir-name{overflow-wrap:anywhere}
.dir-meta{display:block;font-family:var(--font-ui);font-size:18px;line-height:1.1;opacity:.7;padding-bottom:4px}
.dir-more{margin-top:10px;padding:4px 10px;font-family:var(--font-pixel);font-size:inherit;line-height:1.6;background:#a7a4ff;color:#2e2c9b;border:0;cursor:pointer}

/* Disk box */
.shelf{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:22px;margin:0 0 52px}
.book{display:flex;flex-direction:column;color:var(--text);text-decoration:none;transition:transform .12s}
.book:hover{transform:translate(-3px,-3px);color:var(--text)}
.book-cover{position:relative;aspect-ratio:3/4;overflow:hidden;padding:14px 14px 0;background:var(--bc);border:3px solid #000;box-shadow:6px 6px 0 rgba(0,0,0,.45);display:flex;flex-direction:column;gap:10px}
.book-brand{font-family:var(--font-ui);font-size:17px;line-height:1;letter-spacing:.14em;color:rgba(255,255,255,.85)}
.book-cover-title{font-family:var(--font-pixel);font-size:11px;line-height:1.7;color:#fff;text-shadow:2px 2px 0 rgba(0,0,0,.5);overflow-wrap:anywhere;text-transform:uppercase}
.book-stripes{position:absolute;left:-10%;right:-10%;bottom:16%;height:34px;transform:rotate(-14deg);background:linear-gradient(to bottom,#e8423a 0 20%,#f28b2c 20% 40%,#f5d43a 40% 60%,#58b947 60% 80%,#3a7fe0 80% 100%)}
.book-cover::after{content:'64';position:absolute;right:10px;bottom:8px;font-family:var(--font-pixel);font-size:20px;color:#fff;text-shadow:2px 2px 0 #000}
.book-info{padding:12px 2px 0}
.book-name{font-family:var(--font-ui);font-size:23px;line-height:1.05;color:var(--link)}
.book-count{margin-top:4px;font-family:var(--font-ui);font-size:18px;color:var(--muted);text-transform:uppercase}

/* Extras */
.extras{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:18px;margin:0 0 24px}
.extra{display:flex;flex-direction:column;gap:8px;padding:18px 18px 20px;background:var(--surface);border:3px solid var(--xc,#706deb);color:var(--text);text-decoration:none}
.extra:hover{color:var(--text);filter:brightness(1.15)}
.extra-icon{font-family:var(--font-pixel);font-size:18px;line-height:1.4;color:var(--xc,#706deb)}
.extra-name{font-family:var(--font-ui);font-size:26px;line-height:1.1;text-transform:uppercase}
.extra-text{font-size:14px;line-height:1.45;color:var(--muted)}
.extra.soon{border-style:dashed;pointer-events:none;opacity:.55}
.hub-more .widget{margin:0}
.hub-more .widget > .title{display:none}

/* ---------- Paper mode (printer output) ---------- */
html[data-mode="light"]{--border:#d6d0bf;--screen:#f8f5ec;--surface:#fffdf7;--text:#1d1d1d;--muted:#5d5a52;--rule:#2e2c9b;
  --heading:#2e2c9b;--link:#1d4fb8;--link-hover:#8e3c97;--accent:#a12a2a;--status-bg:#2e2c9b;--status-text:#ffffff;
  --l-bg:#ffffff;--l-text:#1d1d1d;--l-kw:#000000;--l-num:#2e2c9b;--l-str:#1e6b2a;--l-rem:#6b6b6b}
html[data-mode="light"] .c64-screenarea{padding:0 30px;box-shadow:0 2px 12px rgba(0,0,0,.12);
  background:radial-gradient(circle at 9px 15px,#d6d0bf 0 6px,transparent 6.5px) left 6px top 0/18px 30px repeat-y,
             radial-gradient(circle at 9px 15px,#d6d0bf 0 6px,transparent 6.5px) right 6px top 0/18px 30px repeat-y,#f8f5ec}
@media (max-width:600px){html[data-mode="light"] .c64-screenarea{padding:0 18px}}
html[data-mode="light"] .boot{color:#5d5a52}
html[data-mode="light"] .listing-wrap{border-color:#9d978a;box-shadow:6px 6px 0 rgba(0,0,0,.12)}
html[data-mode="light"] .listing-bar{background:#2e2c9b;color:#fff}
html[data-mode="light"] .listing-actions button{background:#fff;color:#2e2c9b}
html[data-mode="light"] .listing-typed{background:#fff;color:#1e6b2a}
html[data-mode="light"] .listing-screen{padding:12px 34px;background:repeating-linear-gradient(to bottom,#ffffff 0 72px,#e3f1df 72px 144px) 0 12px/100% 144px,#fff}
html[data-mode="light"] .listing-code .line:hover{background:rgba(46,44,155,.07)}
html[data-mode="light"] .listing-code .dat{color:#0f5f73}
html[data-mode="light"] .pc{background:#1d1d1d;color:#fff}
html[data-mode="light"] .pc-col{background:var(--pc);color:#000}
html[data-mode="light"] .pc-col.pc-dark{color:#fff}
html[data-mode="light"] .listing-legend{border-top-color:#c9c3b5;color:#1d1d1d}
html[data-mode="light"] .listing-legend summary{color:#2e2c9b}
html[data-mode="light"] .post-body code{background:#efece2}
html[data-mode="light"] .post-body pre.code{background:#efece2;color:#1d1d1d}
html[data-mode="light"] .post-body pre.code .dim{color:#6b6b6b}

@media (max-width:600px){
  body{font-size:16px}
  .post-outer-container{padding:20px 14px}
  .menu .LinkList{margin-left:0}
  .menu .LinkList .widget-content{left:0;right:auto}
  pre.listing-code{font-size:11px;line-height:22px}
  .listing-code .line{min-height:22px;padding-left:26px}
}
@media (prefers-reduced-motion:reduce){
  .cursor,.site-header h1,.site-header h2,html.tape body::before{animation:none !important}
}
@media print{.status-bar,.to-top,.sidebar,.menu-bar,.listing-actions{display:none !important}}

head.b:template-skin:
body#layout .status-bar,body#layout .site-footer p,body#layout .boot{display:none}
body#layout .layout{display:flex;gap:16px}
body#layout .main-col{width:66%}
body#layout .sidebar{width:34%}
body#layout .menu{display:block}

body.script:
//
(function(){
  'use strict';
  var root = document.documentElement, body = document.body;
  var isItem = body.classList.contains('is-item'), isHome = body.classList.contains('is-home');
  var reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);

  /* ===== Labels used by the home page ===== */
  var CFG = {
    listingLabel: 'Listing',
    bookPrefix: /^disk\s*:\s*/i,
    hiddenLabels: ['Listing', 'Guide', 'Errata', 'Emulators', 'News'],
    pageSize: 10,
    extras: [
      { label: 'Guide',     icon: '?',   name: 'Type-in guide', text: 'How to type, save and run the listings.',    color: '#75cec8' },
      { label: 'Errata',    icon: '!',   name: 'Errata',        text: 'Bugs in the listings, found and fixed.',      color: '#ff8a8a' },
      { label: 'Emulators', icon: '64',  name: 'Emulators',     text: 'Run the .PRG files in VICE or in a browser.', color: '#a9ff9f' },
      { label: 'News',      icon: 'NEW', name: 'News',          text: 'What is new on the disk.',                   color: '#edf171' }
    ]
  };

  function track(ev, params){ try { if (window.gtag) window.gtag('event', ev, params || {}); } catch (e) {} }
  function el(tag, cls, text){ var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
  function get(k){ try { return localStorage.getItem(k); } catch (e) { return null; } }
  function set(k, v){ try { localStorage.setItem(k, v); } catch (e) {} }
  function each(list, fn){ Array.prototype.forEach.call(list, fn); }

  /* ---------- SID sounds (off by default) ---------- */
  var soundOn = false, actx = null;
  function tone(freq, dur, delay, type, vol){
    if (!soundOn) return;
    try {
      actx = actx || new (window.AudioContext || window.webkitAudioContext)();
      var t = actx.currentTime + (delay || 0), o = actx.createOscillator(), g = actx.createGain();
      o.type = type || 'square'; o.frequency.setValueAtTime(freq, t);
      g.gain.setValueAtTime(vol || 0.035, t); g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(g); g.connect(actx.destination); o.start(t); o.stop(t + dur + 0.02);
    } catch (e) {}
  }
  var TUNES = {
    key: [[1400,.02,0,'square',.015]], click: [[880,.03,0,'square',.025]],
    ok: [[523,.07,0,'triangle',.07],[784,.1,.07,'triangle',.07]],
    ready: [[659,.06,0,'square',.03],[988,.09,.07,'square',.03]],
    save: [[220,.06,0,'sawtooth',.03],[330,.06,.06,'sawtooth',.03],[440,.06,.12,'sawtooth',.03],[880,.14,.18,'triangle',.05]],
    tick: [[1046,.04,0,'triangle',.05]], untick: [[392,.05,0,'triangle',.05]]
  };
  function sfx(n){ (TUNES[n] || []).forEach(function(x){ tone(x[0], x[1], x[2], x[3], x[4]); }); }
  window.c64Sound = sfx;

  /* ---------- Status bar buttons ---------- */
  function setVal(id, v){ var b = document.getElementById(id); if (b){ var s = b.querySelector('.val'); if (s) s.textContent = v; } }
  var lightQ = window.matchMedia ? window.matchMedia('(prefers-color-scheme: light)') : null;
  function applyTheme(t){
    var m = t === 'paper' ? 'light' : (t === 'auto' ? (lightQ && lightQ.matches ? 'light' : 'dark') : 'dark');
    root.setAttribute('data-theme', t); root.setAttribute('data-mode', m); setVal('sb-theme', t.toUpperCase());
  }
  function applyCrt(v){ root.setAttribute('data-crt', v); setVal('sb-crt', v.toUpperCase()); }
  function applySound(v){ soundOn = v === 'on'; setVal('sb-sound', v.toUpperCase()); }
  function toggle(id, key, values, def, apply){
    var cur = get(key) || def; if (values.indexOf(cur) < 0) cur = def; apply(cur);
    var b = document.getElementById(id);
    if (b) b.addEventListener('click', function(){
      cur = values[(values.indexOf(cur) + 1) % values.length]; set(key, cur); apply(cur);
      sfx(id === 'sb-sound' && cur === 'on' ? 'ok' : 'click');
    });
  }
  toggle('sb-theme', 'c64Theme', ['c64', 'paper', 'auto'], 'c64', applyTheme);
  toggle('sb-crt', 'c64Crt', ['on', 'off'], 'on', applyCrt);
  toggle('sb-sound', 'c64Sound', ['off', 'on'], 'off', applySound);
  if (lightQ && lightQ.addEventListener) lightQ.addEventListener('change', function(){ if (root.getAttribute('data-theme') === 'auto') applyTheme('auto'); });

  /* ---------- Tape loading stripes ---------- */
  function tape(ms){
    if (reduce) return;
    root.classList.add('tape');
    if (soundOn) for (var t = 0; t < ms / 1000; t += 0.045) tone(300 + Math.random() * 2200, 0.03, t, 'square', 0.012);
    setTimeout(function(){ root.classList.remove('tape'); }, ms);
  }

  /* ---------- Boot screen (home page) ---------- */
  var firstBoot = root.classList.contains('first-boot');
  try { sessionStorage.setItem('c64Booted', '1'); } catch (e) {}
  var sbTitle = document.querySelector('.sb-title');
  var blogTitle = sbTitle ? sbTitle.textContent.trim() : document.title;
  var T16 = blogTitle.toUpperCase().slice(0, 16) || 'BLOG';
  var boot = document.getElementById('boot');
  if (boot){
    var head = '    **** COMMODORE 64 BASIC V2 ****\n\n 64K RAM SYSTEM  38911 BASIC BYTES FREE\n\nREADY.\n';
    var rest = ['LOAD"' + T16 + '",8,1', '', 'SEARCHING FOR ' + T16, 'LOADING', 'READY.', 'RUN'];
    var cur = el('span', 'cursor', ' '), txt = head;
    var show = function(){ boot.textContent = txt; boot.appendChild(cur); };
    if (firstBoot && !reduce){
      show();
      var ci = 0, cmd = rest[0];
      var typeCh = function(){
        if (ci < cmd.length){ txt += cmd.charAt(ci++); show(); sfx('key'); setTimeout(typeCh, 40 + Math.random() * 60); return; }
        txt += '\n\n'; show();
        setTimeout(function(){
          txt += rest[2] + '\n'; show();
          setTimeout(function(){
            txt += rest[3] + '\n'; show(); tape(1600);
            setTimeout(function(){ txt += 'READY.\nRUN\n'; show(); sfx('ready'); setTimeout(function(){ boot.className += ' done'; }, 900); }, 1650);
          }, 650);
        }, 450);
      };
      setTimeout(typeCh, 500);
    } else { boot.style.display = 'none'; }
  } else if (firstBoot) { tape(800); }

  /* ---------- Tape counter while reading a post ---------- */
  var sbState = document.getElementById('sb-state'), sbCounter = document.getElementById('sb-counter');
  var postBody = isItem ? document.querySelector('.post-body') : null;
  if (sbState && !isItem){ sbState.textContent = 'READY. '; sbState.appendChild(el('span', 'cursor', ' ')); }
  if (postBody && sbCounter && sbState){
    sbState.textContent = 'PRESS PLAY ON TAPE';
    var lastC = -1, idle = null, playing = false, ticking = false;
    var upd = function(){
      ticking = false;
      var r = postBody.getBoundingClientRect();
      var p = Math.min(1, Math.max(0, (window.innerHeight * 0.5 - r.top) / Math.max(r.height, 1)));
      var c = Math.round(p * 999);
      if (c !== lastC){ sbCounter.textContent = ('00' + c).slice(-3); lastC = c; }
    };
    window.addEventListener('scroll', function(){
      if (!ticking){ ticking = true; requestAnimationFrame(upd); }
      if (!playing){ playing = true; sbState.textContent = '▶ PLAY'; }
      clearTimeout(idle);
      idle = setTimeout(function(){ playing = false; sbState.textContent = lastC >= 999 ? 'READY.' : '■ STOP'; }, 450);
    }, { passive: true });
    upd();
  }

  /* ---------- C64 screenshots -> crisp pixels ---------- */
  function toOriginal(src){
    return src.replace(/\/(?:s\d+|w\d+-h\d+)(?:-[a-z0-9-]+)?\/([^\/?#]+)$/i, '/s0/$1').replace(/=(?:s\d+|w\d+-h\d+)(?:-[a-z0-9-]+)?$/i, '=s0');
  }
  var SHOT = [1.6, 1.4118, 1.419];
  function fixImg(img){
    var w = img.naturalWidth, h = img.naturalHeight;
    if (!w || !h) return;
    var r = w / h, ok = SHOT.some(function(x){ return Math.abs(r - x) < 0.012; });
    if (!ok || w > 820){ img.classList.remove('c64-shot'); return; }
    var src = img.currentSrc || img.src;
    if (/googleusercontent\.com|bp\.blogspot\.com/i.test(src)){ var o = toOriginal(src); if (o !== src){ img.removeAttribute('srcset'); img.src = o; } }
    img.classList.add('c64-shot');
  }
  each(document.querySelectorAll('.post-body img'), function(img){
    if (img.complete) fixImg(img);
    img.addEventListener('load', function(){ fixImg(img); });
  });

  /* ==========================================================
     LISTING ENGINE: BASIC V2 colouring + tokenizer -> .PRG
     ========================================================== */
  /* LISTING-ENGINE-START */
  var KW = ['END','FOR','NEXT','DATA','INPUT#','INPUT','DIM','READ','LET','GOTO','RUN','IF','RESTORE','GOSUB','RETURN','REM',
    'STOP','ON','WAIT','LOAD','SAVE','VERIFY','DEF','POKE','PRINT#','PRINT','CONT','LIST','CLR','CMD','SYS','OPEN','CLOSE',
    'GET','NEW','TAB(','TO','FN','SPC(','THEN','NOT','STEP','+','-','*','/','^','AND','OR','>','=','<','SGN','INT','ABS',
    'USR','FRE','POS','SQR','RND','LOG','EXP','COS','SIN','TAN','ATN','PEEK','LEN','STR$','VAL','ASC','CHR$','LEFT$',
    'RIGHT$','MID$','GO'];
  var KWB = KW.map(function(k){ return k.split('').map(function(c){ return c === '^' ? 0x5E : c.charCodeAt(0); }); });

  var CODES = {};
  function def(names, b, key, col){ names.split('|').forEach(function(n){ CODES[n] = { b: b, key: key, col: col }; }); }
  def('CLR|CLEAR|CLS|SC|SHIFTCLR|SHIFTCLRHOME', 0x93, 'SHIFT + CLR/HOME');
  def('HOME|HOM|CLRHOME', 0x13, 'CLR/HOME');
  def('DOWN|DN|CD|CRSRDN', 0x11, 'CRSR ⇕');
  def('UP|CU|CRSRUP', 0x91, 'SHIFT + CRSR ⇕');
  def('RIGHT|RGHT|RGT|RT|CR', 0x1D, 'CRSR ⇔');
  def('LEFT|LFT|LT|CL', 0x9D, 'SHIFT + CRSR ⇔');
  def('RVSON|RVS|RVON|REVON|REV|REVERSEON|RON', 0x12, 'CTRL + 9 (RVS ON)');
  def('RVSOFF|RVOFF|RVOF|REVOFF|REVERSEOFF|ROFF|OFF', 0x92, 'CTRL + 0 (RVS OFF)');
  def('BLK|BLACK', 0x90, 'CTRL + 1', 0);
  def('WHT|WHITE', 0x05, 'CTRL + 2', 1);
  def('RED', 0x1C, 'CTRL + 3', 2);
  def('CYN|CYAN', 0x9F, 'CTRL + 4', 3);
  def('PUR|PURPLE|PURP|PRP', 0x9C, 'CTRL + 5', 4);
  def('GRN|GREEN', 0x1E, 'CTRL + 6', 5);
  def('BLU|BLUE', 0x1F, 'CTRL + 7', 6);
  def('YEL|YELLOW|YELO', 0x9E, 'CTRL + 8', 7);
  def('ORNG|ORANGE|ORG|ORN', 0x81, 'C= + 1', 8);
  def('BRN|BROWN', 0x95, 'C= + 2', 9);
  def('LRED|LTRED|LIGHTRED|PINK', 0x96, 'C= + 3', 10);
  def('GRY1|GREY1|DGRY|DKGRY|DKGRAY|DARKGRAY|DARKGREY', 0x97, 'C= + 4', 11);
  def('GRY2|GREY2|GRY|GRAY|GREY|MGRY|MEDGRAY|MEDGREY', 0x98, 'C= + 5', 12);
  def('LGRN|LTGRN|LTGREEN|LIGHTGREEN', 0x99, 'C= + 6', 13);
  def('LBLU|LTBLU|LTBLUE|LIGHTBLUE', 0x9A, 'C= + 7', 14);
  def('GRY3|GREY3|LGRY|LTGRY|LTGRAY|LIGHTGRAY|LIGHTGREY', 0x9B, 'C= + 8', 15);
  def('F1', 0x85, 'F1'); def('F3', 0x86, 'F3'); def('F5', 0x87, 'F5'); def('F7', 0x88, 'F7');
  def('F2', 0x89, 'SHIFT + F1'); def('F4', 0x8A, 'SHIFT + F3'); def('F6', 0x8B, 'SHIFT + F5'); def('F8', 0x8C, 'SHIFT + F7');
  def('INST|INSERT|INS', 0x94, 'SHIFT + INST/DEL');
  def('DEL|DELETE', 0x14, 'INST/DEL');
  def('SPACE|SPC|SP', 0x20, 'SPACE');
  def('SHIFTSPACE|SHSPACE|SHIFTSPC', 0xA0, 'SHIFT + SPACE');
  def('PI', 0xFF, 'SHIFT + ↑');
  def('POUND|LB', 0x5C, '£');
  def('UPARROW|ARROWUP', 0x5E, '↑');
  def('LEFTARROW|BACKARROW|ARROWLEFT', 0x5F, '←');
  def('RETURN|RET', 0x0D, 'RETURN');
  def('SHIFTRETURN', 0x8D, 'SHIFT + RETURN');
  def('STOP|RUNSTOP', 0x03, 'RUN/STOP');
  def('LOWERCASE|LC|SWLC', 0x0E, 'CTRL + N');
  def('UPPERCASE|UC|SWUC', 0x8E, 'CHR$(142)');
  def('DISABLE', 0x08, 'CTRL + H');
  def('ENABLE', 0x09, 'CTRL + I');
  var SHIFTSYM = { '*': 0xC0, '+': 0xDB, '-': 0xDD, '£': 0xA9, '@': 0xBA, '^': 0xDE, '↑': 0xDE };
  var CBMMAP = { A:0xB0,B:0xBF,C:0xBC,D:0xAC,E:0xB1,F:0xBB,G:0xA5,H:0xB4,I:0xA2,J:0xB5,K:0xA1,L:0xB6,M:0xA7,N:0xAA,O:0xB9,
    P:0xAF,Q:0xAB,R:0xB2,S:0xAE,T:0xA3,U:0xB8,V:0xBE,W:0xB3,X:0xBD,Y:0xB7,Z:0xAD,'+':0xA6,'-':0xDC,'£':0xA8,'*':0xDF,'@':0xA4 };
  var PAL = ['#000000','#ffffff','#813338','#75cec8','#8e3c97','#56ac4d','#2e2c9b','#edf171','#8e5029','#553800','#c46c71','#4a4a4a','#7b7b7b','#a9ff9f','#706deb','#b2b2b2'];
  var DARK = { 0:1, 2:1, 4:1, 6:1, 8:1, 9:1, 11:1, 12:1 };

  function lookupCode(raw){
    var u = raw.trim().toUpperCase(), m;
    var n = u.replace(/^CRSR[\s\-]*/, '').replace(/[\s\-_.\/]+/g, '');
    if (CODES[n]) return CODES[n];
    if (n.length > 3 && n.slice(-1) === 'S' && CODES[n.slice(0, -1)]) return CODES[n.slice(0, -1)];
    if ((m = u.match(/^(?:SHIFT|SHFT|SH)[\s\-+]*(.)$/))){
      var s = m[1];
      if (/[A-Z]/.test(s)) return { b: 0xC0 + s.charCodeAt(0) - 64, key: 'SHIFT + ' + s };
      if (SHIFTSYM[s] != null) return { b: SHIFTSYM[s], key: 'SHIFT + ' + s };
    }
    if ((m = u.match(/^(?:CBM|C=|COMMODORE|COMM)[\s\-+]*(.)$/)) && CBMMAP[m[1]] != null) return { b: CBMMAP[m[1]], key: 'C= + ' + m[1] };
    if ((m = u.match(/^\$([0-9A-F]{1,2})$/))){ var hx = parseInt(m[1], 16); return { b: hx, key: 'CHR$(' + hx + ')' }; }
    if ((m = u.match(/^(\d{1,3})$/)) && +m[1] < 256) return { b: +m[1], key: 'CHR$(' + m[1] + ')' };
    return null;
  }
  function parseCode(inner){
    var u = inner.trim(), cnt = 1, m;
    if ((m = u.match(/^(\d+)\s*[\s*x×]\s*(\D.*)$/i))){ cnt = +m[1]; u = m[2]; }
    else if ((m = u.match(/^(.*\D)\s*[*×]\s*(\d+)$/))){ cnt = +m[2]; u = m[1]; }
    var c = lookupCode(u);
    if (!c) return null;
    cnt = Math.max(1, Math.min(cnt, 255));
    var bytes = []; for (var i = 0; i < cnt; i++) bytes.push(c.b);
    return { bytes: bytes, code: c, name: u.trim().toUpperCase(), count: cnt };
  }
  var UNI = { '£': 0x5C, '↑': 0x5E, '^': 0x5E, '←': 0x5F, 'π': 0xFF, ' ': 0x20, '\t': 0x20 };
  function toBytes(s, warn){
    var out = [];
    for (var i = 0; i < s.length; i++){
      var ch = s.charAt(i);
      if (ch === '{'){
        var j = s.indexOf('}', i);
        if (j > i){
          var r = parseCode(s.slice(i + 1, j));
          if (r){ Array.prototype.push.apply(out, r.bytes); i = j; continue; }
          warn.push(s.slice(i, j + 1));
        }
      }
      var cc = ch.charCodeAt(0);
      if (UNI[ch] != null){ out.push(UNI[ch]); continue; }
      if (cc >= 97 && cc <= 122){ out.push(cc - 32); continue; }
      if (cc >= 32 && cc <= 93){ out.push(cc); continue; }
      out.push(0x3F); if (ch !== '{') warn.push(ch);
    }
    return out;
  }
  function crunch(b){
    var out = [], i = 0, q = false, mode = 0;
    while (i < b.length){
      var c = b[i];
      if (mode === 2){ out.push(c); i++; continue; }
      if (c === 0x22){ q = !q; out.push(c); i++; continue; }
      if (q){ out.push(c); i++; continue; }
      if (mode === 1){ if (c === 0x3A) mode = 0; out.push(c); i++; continue; }
      if (c === 0x20){ out.push(c); i++; continue; }
      if (c === 0x3F){ out.push(0x99); i++; continue; }
      if (c >= 0x30 && c <= 0x3B){ out.push(c); i++; continue; }
      var hit = -1;
      for (var k = 0; k < KWB.length && hit < 0; k++){
        var w = KWB[k], ok = true;
        for (var x = 0; x < w.length; x++) if (b[i + x] !== w[x]){ ok = false; break; }
        if (ok) hit = k;
      }
      if (hit >= 0){
        var tok = 0x80 + hit; out.push(tok); i += KWB[hit].length;
        if (tok === 0x83) mode = 1; else if (tok === 0x8F) mode = 2;
        continue;
      }
      out.push(c); i++;
    }
    return out;
  }
  function parseListing(text){
    var rows = text.replace(/\r/g, '').replace(/ /g, ' ').replace(/^\s*\n/, '').replace(/\s+$/, '').split('\n');
    var warn = [], byNum = {}, nums = [];
    rows.forEach(function(t){
      var m = t.match(/^\s*(\d{1,5})(.*)$/);
      if (!m) return;
      var n = +m[1];
      if (n > 63999){ warn.push('line ' + n + ' > 63999'); return; }
      if (!(n in byNum)) nums.push(n);
      byNum[n] = m[2].replace(/^ +/, '');
    });
    nums.sort(function(a, b){ return a - b; });
    var prg = [0x01, 0x08], addr = 0x0801;
    nums.forEach(function(n){
      var body = crunch(toBytes(byNum[n], warn));
      var next = addr + 4 + body.length + 1;
      prg.push(next & 255, next >> 8, n & 255, n >> 8);
      Array.prototype.push.apply(prg, body); prg.push(0);
      addr = next;
    });
    prg.push(0, 0);
    return { rows: rows, prg: prg, count: nums.length, warn: warn, blocks: Math.ceil(prg.length / 254) };
  }
  /* LISTING-ENGINE-END */

  function readSource(node){
    if (node.tagName === 'SCRIPT') return node.textContent || '';
    if (node.tagName === 'TEXTAREA') return node.value || node.textContent || '';
    var tmp = node.ownerDocument.createElement('div');
    tmp.innerHTML = node.innerHTML.replace(/<br\s*\/?>/gi, '\n');
    return tmp.textContent || '';
  }
  function chip(text, c){
    var s = el('span', 'pc', text);
    s.title = c.key;
    if (c.col != null){ s.className += ' pc-col' + (DARK[c.col] ? ' pc-dark' : ''); s.style.setProperty('--pc', PAL[c.col]); }
    return s;
  }
  function renderBody(s, line, used){
    var segs = [];
    function seg(cls, t){ var L = segs[segs.length - 1]; if (L && !L.node && L.cls === cls) L.t += t; else segs.push({ cls: cls, t: t }); }
    var i = 0, q = false, mode = 0, U = s.toUpperCase();
    while (i < s.length){
      var ch = s.charAt(i);
      if (ch === '{'){
        var j = s.indexOf('}', i);
        if (j > i){
          var r = parseCode(s.slice(i + 1, j));
          if (r){
            if (!used[r.code.b]) used[r.code.b] = { name: r.name, code: r.code };
            segs.push({ node: chip((r.count > 1 ? r.count + ' ' : '') + r.name, r.code) }); i = j + 1; continue;
          }
        }
      }
      if (mode === 2){ seg('rem', ch); i++; continue; }
      if (ch === '"'){ q = !q; seg('str', ch); i++; continue; }
      if (q){ seg('str', ch); i++; continue; }
      if (mode === 1){ if (ch === ':'){ mode = 0; seg(null, ch); } else seg('dat', ch); i++; continue; }
      if (ch === ' ' || /[0-9:;]/.test(ch)){ seg(null, ch); i++; continue; }
      if (ch === '?'){ seg('kw', ch); i++; continue; }
      var hit = null;
      for (var k = 0; k < KW.length; k++){
        var w = KW[k];
        if (U.substr(i, w.length) === w || (w === '^' && ch === '↑')){ hit = w; break; }
      }
      if (hit){
        var len = hit === '^' ? 1 : hit.length;
        seg(/^[A-Z]/.test(hit) ? 'kw' : null, s.substr(i, len)); i += len;
        if (hit === 'DATA') mode = 1; else if (hit === 'REM') mode = 2;
        continue;
      }
      seg(null, ch); i++;
    }
    segs.forEach(function(g){
      if (g.node) line.appendChild(g.node);
      else if (g.cls) line.appendChild(el('span', g.cls, g.t));
      else line.appendChild(document.createTextNode(g.t));
    });
  }
  function slugify(t){ return (t || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 40); }
  function copyText(t, done){
    function fallback(){ var a = document.createElement('textarea'); a.value = t; a.style.position = 'fixed'; a.style.opacity = '0'; document.body.appendChild(a); a.select(); try { document.execCommand('copy'); done(); } catch (e) {} document.body.removeChild(a); }
    if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(t).then(done, fallback); else fallback();
  }
  function download(name, data, type){
    var blob = new Blob([data], { type: type }), url = URL.createObjectURL(blob), a = document.createElement('a');
    a.href = url; a.download = name; document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(function(){ URL.revokeObjectURL(url); }, 2000);
  }

  var titleEl = document.querySelector('.post-title');
  var postTitle = titleEl ? titleEl.textContent.trim() : document.title;
  var nodes = document.querySelectorAll('.post-body pre.listing, .post-body script.listing, .post-body textarea.listing');
  each(nodes, function(node, idx){
    var raw = readSource(node).replace(/ /g, ' ').replace(/^\s*\n/, '').replace(/\s+$/, '');
    var L = parseListing(raw);
    var given = node.getAttribute('data-name');
    var name = (given || postTitle).toUpperCase().slice(0, 16);
    var file = slugify(given || postTitle) || 'program';
    if (nodes.length > 1 && !given) file += '-' + (idx + 1);

    var fig = el('figure', 'listing-wrap');
    var bar = el('figcaption', 'listing-bar');
    bar.appendChild(el('span', 'listing-name', '"' + name + '"'));
    bar.appendChild(el('span', 'listing-meta', L.count + ' LINES · ' + L.blocks + (L.blocks === 1 ? ' BLOCK' : ' BLOCKS')));
    var typedEl = el('span', 'listing-typed', ''); bar.appendChild(typedEl);
    if (L.warn.length){
      var wEl = el('span', 'listing-warn', '⚠ ' + L.warn.length);
      wEl.title = 'Not understood (saved as ?): ' + L.warn.slice(0, 12).join('  ');
      bar.appendChild(wEl);
    }
    var acts = el('span', 'listing-actions');
    var bCopy = el('button', null, 'Copy'), bPrg = el('button', null, '↓ .PRG'), bTxt = el('button', null, '↓ .TXT'), bFont = el('button', null, 'Aa'), bClr = el('button', null, 'Clr');
    [bCopy, bPrg, bTxt, bFont, bClr].forEach(function(b){ b.type = 'button'; acts.appendChild(b); });
    bPrg.title = 'Download a ready-to-run program for VICE or an online C64 emulator';
    bTxt.title = 'Download the listing as text';
    bFont.title = 'C64 font or plain font';
    bClr.title = 'Clear the typed-in marks';
    bar.appendChild(acts);
    fig.appendChild(bar);

    var scr = el('div', 'listing-screen'), pre = el('pre', 'listing-code'), used = {};
    pre.title = 'Click a line to tick it off as typed';
    L.rows.forEach(function(t){
      var line = el('span', 'line'), m = t.match(/^\s*(\d{1,5})(.*)$/);
      if (m){
        line.appendChild(el('span', 'lnum', m[1]));
        line.appendChild(document.createTextNode(' '));
        renderBody(m[2].replace(/^ +/, ''), line, used);
      } else { line.className += ' note'; line.textContent = t.length ? t : ' '; }
      pre.appendChild(line);
    });
    scr.appendChild(pre); fig.appendChild(scr);

    var keys = Object.keys(used);
    if (keys.length){
      var det = el('details', 'listing-legend');
      det.appendChild(el('summary', null, 'How to type the {codes} (' + keys.length + ')'));
      var dl = el('dl');
      keys.forEach(function(k){ var u = used[k], dt = el('dt'); dt.appendChild(chip(u.name, u.code)); dl.appendChild(dt); dl.appendChild(el('dd', null, u.code.key)); });
      det.appendChild(dl); fig.appendChild(det);
    }

    var all = Array.prototype.slice.call(pre.children);
    var total = all.filter(function(x){ return x.className.indexOf('note') < 0; }).length;
    var key = 'c64typed:' + location.pathname + '#' + idx, done = {};
    try { (JSON.parse(get(key) || '[]') || []).forEach(function(i){ done[i] = 1; }); } catch (e) {}
    function paint(){
      var n = 0;
      all.forEach(function(ln, i){ var on = !!done[i]; ln.classList.toggle('done', on); if (on) n++; });
      typedEl.textContent = n === total ? 'ALL TYPED. RUN!' : 'TYPED ' + n + '/' + total;
      typedEl.style.display = n ? '' : 'none';
      bClr.style.display = n ? '' : 'none';
    }
    function save(){ set(key, JSON.stringify(Object.keys(done).map(Number))); }
    pre.addEventListener('click', function(e){
      var ln = e.target.closest('.line'); if (!ln || ln.classList.contains('note')) return;
      var sel = window.getSelection && window.getSelection(); if (sel && !sel.isCollapsed) return;
      var i = all.indexOf(ln);
      if (done[i]){ delete done[i]; sfx('untick'); } else { done[i] = 1; sfx('tick'); }
      save(); paint();
      if (Object.keys(done).length === total){ sfx('ready'); track('listing_typed', { program: name, lines: total }); }
    });
    bClr.addEventListener('click', function(){ done = {}; save(); paint(); sfx('click'); });
    paint();
    bCopy.addEventListener('click', function(){ copyText(raw, function(){ bCopy.textContent = 'Copied'; sfx('ok'); setTimeout(function(){ bCopy.textContent = 'Copy'; }, 1300); }); track('listing_copy', { program: name }); });
    bPrg.addEventListener('click', function(){ download(file + '.prg', new Uint8Array(L.prg), 'application/octet-stream'); tape(700); sfx('save'); track('file_download', { file_name: file + '.prg', file_extension: 'prg', program: name }); });
    bTxt.addEventListener('click', function(){ download(file + '.txt', raw + '\n', 'text/plain;charset=utf-8'); sfx('click'); });
    bFont.addEventListener('click', function(){ var f = root.getAttribute('data-font') === 'mono' ? 'c64' : 'mono'; root.setAttribute('data-font', f); set('c64Font', f); sfx('click'); });

    node.parentNode.insertBefore(fig, node);
    node.parentNode.removeChild(node);
  });

  /* ---------- Table of contents (3+ headings) ---------- */
  if (postBody && !postBody.querySelector('.no-toc')){
    var hs = postBody.querySelectorAll('h2, h3');
    if (hs.length >= 3){
      var nav = el('nav', 'toc'); nav.appendChild(el('p', 'toc-title', 'LIST'));
      var ul = el('ul');
      each(hs, function(h, i){
        if (!h.id) h.id = 's' + (i + 1) + '-' + slugify(h.textContent);
        var li = el('li', h.tagName === 'H3' ? 'lvl3' : 'lvl2'), a = el('a', null, h.textContent); a.href = '#' + h.id;
        li.appendChild(a); ul.appendChild(li);
      });
      nav.appendChild(ul); hs[0].parentNode.insertBefore(nav, hs[0]);
    }
  }

  /* ---------- Sidebar labels: "Disk:X" -> "X", hide internal labels ---------- */
  var sideHidden = [CFG.listingLabel.toLowerCase()];
  each(document.querySelectorAll('.sidebar .Label li'), function(li){
    var a = li.querySelector('a') || li, tn = null;
    for (var k = 0; k < a.childNodes.length; k++){ if (a.childNodes[k].nodeType === 3 && a.childNodes[k].nodeValue.trim()){ tn = a.childNodes[k]; break; } }
    if (!tn) return;
    var t = tn.nodeValue.trim();
    if (sideHidden.indexOf(t.toLowerCase()) > -1){ li.parentNode.removeChild(li); return; }
    if (CFG.bookPrefix.test(t)){ tn.nodeValue = tn.nodeValue.replace(/^(\s*)disk\s*:\s*/i, '$1'); li.className += ' is-book'; }
  });
  var books = Array.prototype.filter.call(document.querySelectorAll('.sidebar .Label li'), function(li){ return li.className.indexOf('is-book') > -1; });
  books.forEach(function(li){ li.parentNode.insertBefore(li, li.parentNode.firstChild); });

  /* ---------- "More sites" dropdown ---------- */
  var ll = document.querySelector('.menu .LinkList');
  if (ll){
    var lt = ll.querySelector('.title');
    if (lt){
      lt.setAttribute('tabindex', '0');
      lt.addEventListener('click', function(){ ll.classList.toggle('open'); });
      document.addEventListener('click', function(e){ if (!ll.contains(e.target)) ll.classList.remove('open'); });
    }
  }

  /* ==========================================================
     HOME PAGE: disk directory + disk box + extras
     ========================================================== */
  var hub = document.getElementById('hub');
  /* Blogger returns at most 150 posts per request: read them in pages */
  function loadFeed(start, acc){
    return window.fetch(location.origin + '/feeds/posts/default?alt=json&max-results=150&start-index=' + start)
      .then(function(r){ return r.json(); })
      .then(function(d){
        var e = (d.feed && d.feed.entry) || [];
        acc = acc.concat(e);
        return (e.length === 150 && start < 1500) ? loadFeed(start + 150, acc) : acc;
      });
  }
  if (hub && isHome){
    var hero = document.getElementById('hub-hero');
    if (hero && !hero.querySelector('.hub-info .widget')) hero.className += ' solo';
    if (!(window.fetch && window.DOMParser)) body.classList.add('hub-failed');
    else loadFeed(1, []).then(buildHub).catch(function(){ body.classList.add('hub-failed'); });
  }

  function buildHub(entries){
    var parser = new DOMParser();
    var posts = (entries || []).map(function(e, i){
      var alt = (e.link || []).filter(function(l){ return l.rel === 'alternate'; })[0];
      var html = (e.content || e.summary || {}).$t || '';
      var doc = parser.parseFromString(html, 'text/html'), bytes = 0, lines = 0, prog = '';
      each(doc.querySelectorAll('pre.listing, script.listing, textarea.listing'), function(n){
        var L = parseListing(readSource(n)); bytes += L.prg.length; lines += L.count;
        if (!prog) prog = (n.getAttribute('data-name') || '').trim();
        n.parentNode.removeChild(n);
      });
      var text = (doc.body.textContent || '').replace(/\s+/g, ' ').trim();
      var labels = (e.category || []).map(function(c){ return c.term; });
      return {
        title: (e.title && e.title.$t) || '', prog: prog, url: alt ? alt.href : '#', labels: labels, order: i, lines: lines,
        blocks: Math.max(1, Math.ceil((bytes || text.length) / 254)),
        book: labels.filter(function(l){ return CFG.bookPrefix.test(l); })[0] || ''
      };
    });
    if (!posts.length){ body.classList.add('hub-failed'); return; }
    function has(p, l){ return p.labels.indexOf(l) > -1; }
    function bookName(l){ return l.replace(CFG.bookPrefix, ''); }
    function labelUrl(l){ return location.origin + '/search/label/' + encodeURIComponent(l); }

    var progs = posts.filter(function(p){ return has(p, CFG.listingLabel); });
    if (!progs.length) progs = posts.slice();
    progs.forEach(function(p){
      p.file = p.prog ? p.prog.toUpperCase().slice(0, 16) : p.title.toUpperCase();
      p.sub = p.prog ? p.title.replace(new RegExp('^\\s*' + p.prog.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*[:\u2013\u2014-]\\s*', 'i'), '') : '';
    });

    var latest = document.getElementById('hub-latest');
    if (latest){ latest.textContent = 'NEW: '; var la = el('a', null, posts[0].title); la.href = posts[0].url; latest.appendChild(la); }
    var run = document.getElementById('hub-run'); if (run && progs[0]) run.href = progs[0].url;

    var hidden = CFG.hiddenLabels.map(function(x){ return x.toLowerCase(); });
    function catsOf(p){ return p.labels.filter(function(l){ return !CFG.bookPrefix.test(l) && hidden.indexOf(l.toLowerCase()) < 0; }); }

    /* ----- Disk directory: one disk per Disk: label, type filter, wildcard search ----- */
    var dirBox = document.getElementById('hub-dir'), filt = document.getElementById('hub-filters');
    var diskId = ((blogTitle.match(/\b[A-Za-z0-9]/g) || []).join('') + '64').slice(0, 2).toUpperCase();
    var disk = null, cat = null, pattern = '', shown = CFG.pageSize;
    var disks = {};
    progs.forEach(function(p){ if (p.book) disks[p.book] = (disks[p.book] || 0) + 1; });
    var diskNames = Object.keys(disks).sort(function(a, b){ return bookName(a).localeCompare(bookName(b)); });

    function onDisk(){ return disk ? progs.filter(function(p){ return p.book === disk; }) : progs; }
    function matches(p){
      if (!pattern) return true;
      var q = pattern.toUpperCase();
      if (/[*?]/.test(q)){
        var re = new RegExp('^' + q.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.') + '$');
        return re.test(p.file);
      }
      return p.file.indexOf(q) > -1 || p.title.toUpperCase().indexOf(q) > -1;
    }
    function drawDir(){
      var all = onDisk();
      var list = all.filter(function(p){ return (!cat || has(p, cat)) && matches(p); });
      dirBox.innerHTML = '';
      var d = el('div', 'dir');
      [pattern ? 'LOAD"$:' + pattern.toUpperCase() + '",8' : 'LOAD"$",8', 'SEARCHING FOR $', 'LOADING', 'READY.', 'LIST']
        .forEach(function(t){ d.appendChild(el('p', null, t)); });
      var label = disk ? bookName(disk).toUpperCase().slice(0, 16) : T16;
      d.appendChild(el('div', 'dir-head', '0 "' + (label + '                ').slice(0, 16) + '" ' + diskId + ' 2A'));
      list.slice(0, shown).forEach(function(p){
        var a = el('a', 'dir-row'); a.href = p.url;
        a.appendChild(el('span', 'dir-blk', String(p.blocks)));
        var nm = el('span', 'dir-name', '"' + p.file + '"'), meta = [];
        if (p.sub) meta.push(p.sub);
        if (p.book && !disk) meta.push(bookName(p.book));
        if (p.lines) meta.push(p.lines + ' lines');
        if (meta.length) nm.appendChild(el('span', 'dir-meta', meta.join(' \u00B7 ')));
        a.appendChild(nm); a.appendChild(el('span', 'dir-type', 'PRG'));
        d.appendChild(a);
      });
      if (!list.length) d.appendChild(el('p', null, '?FILE NOT FOUND  ERROR'));
      var used = all.reduce(function(s, p){ return s + p.blocks; }, 0);
      d.appendChild(el('p', null, Math.max(0, 664 - used) + ' BLOCKS FREE.'));
      if (list.length > shown){
        var more = el('button', 'dir-more', 'LIST MORE (' + (list.length - shown) + ')'); more.type = 'button';
        more.addEventListener('click', function(){ shown += CFG.pageSize; drawDir(); sfx('click'); });
        d.appendChild(more);
      }
      d.appendChild(el('p', null, 'READY.'));
      var cp = el('p'); cp.appendChild(el('span', 'cursor', '\u00a0')); d.appendChild(cp);
      dirBox.appendChild(d);
      var hp = document.getElementById('hub-progress');
      if (hp) hp.textContent = all.length + (all.length === 1 ? ' program' : ' programs') + ' \u00B7 ' + used + ' blocks';
    }
    function row(name){ var r = el('div', 'dir-filter-row'); r.appendChild(el('span', 'dir-lbl', name)); return r; }
    function btn(text, on, fn){ var b = el('button', on ? 'on' : '', text); b.type = 'button'; b.setAttribute('aria-pressed', String(!!on)); b.addEventListener('click', fn); return b; }
    var search = null;
    function drawFilters(){
      filt.innerHTML = '';
      if (diskNames.length > 1){
        var r1 = row('DISK');
        r1.appendChild(btn('All (' + progs.length + ')', !disk, function(){ disk = null; cat = null; shown = CFG.pageSize; drawFilters(); drawDir(); sfx('click'); }));
        diskNames.forEach(function(k){
          r1.appendChild(btn(bookName(k) + ' (' + disks[k] + ')', disk === k, function(){ disk = k; cat = null; shown = CFG.pageSize; drawFilters(); drawDir(); sfx('click'); }));
        });
        filt.appendChild(r1);
      }
      var cats = {}, here = onDisk();
      here.forEach(function(p){ catsOf(p).forEach(function(c){ cats[c] = (cats[c] || 0) + 1; }); });
      var names = Object.keys(cats).sort();
      if (names.length){
        var r2 = row('TYPE');
        r2.appendChild(btn('All (' + here.length + ')', !cat, function(){ cat = null; shown = CFG.pageSize; drawFilters(); drawDir(); sfx('click'); }));
        names.forEach(function(c){
          r2.appendChild(btn(c + ' (' + cats[c] + ')', cat === c, function(){ cat = c; shown = CFG.pageSize; drawFilters(); drawDir(); sfx('click'); }));
        });
        filt.appendChild(r2);
      }
      if (progs.length > 1){
        var r3 = el('label', 'dir-search');
        r3.appendChild(el('span', null, 'LOAD"$:'));
        if (!search){
          search = el('input'); search.type = 'text'; search.placeholder = 'BA*'; search.autocomplete = 'off'; search.spellcheck = false;
          search.setAttribute('aria-label', 'Search the directory. Use * and ? as wildcards.');
          search.addEventListener('input', function(){ pattern = search.value.trim(); shown = CFG.pageSize; drawDir(); });
        }
        r3.appendChild(search);
        r3.appendChild(el('span', null, '",8'));
        filt.appendChild(r3);
      }
    }
    drawFilters(); drawDir();

    var books = {};
    posts.forEach(function(p){ if (p.book){ books[p.book] = books[p.book] || { label: p.book, n: 0 }; books[p.book].n++; } });
    var shelf = document.getElementById('hub-shelf'); shelf.innerHTML = '';
    var COLORS = [4, 2, 5, 8, 14, 10, 9, 3, 11, 6];
    var bookList = Object.keys(books).sort(function(a, b){ return bookName(a).localeCompare(bookName(b)); });
    bookList.forEach(function(k){
      var b = books[k], nm = bookName(b.label), h = 0;
      for (var i = 0; i < nm.length; i++) h = (h * 31 + nm.charCodeAt(i)) >>> 0;
      var a = el('a', 'book'); a.href = labelUrl(b.label);
      var cv = el('div', 'book-cover'); cv.style.setProperty('--bc', PAL[COLORS[h % COLORS.length]]);
      cv.appendChild(el('span', 'book-brand', 'COMMODORE'));
      cv.appendChild(el('span', 'book-cover-title', nm));
      cv.appendChild(el('span', 'book-stripes'));
      a.appendChild(cv);
      var info = el('div', 'book-info');
      info.appendChild(el('div', 'book-name', nm));
      info.appendChild(el('div', 'book-count', b.n + (b.n === 1 ? ' program' : ' programs')));
      a.appendChild(info); shelf.appendChild(a);
    });
    if (!bookList.length){
      /* No "Disk: ..." labels yet: hide the disk box */
      shelf.style.display = 'none';
      var dt = document.getElementById('hub-disks-title'); if (dt) dt.style.display = 'none';
    }
    var hb = document.getElementById('hub-books'); if (hb) hb.textContent = bookList.length + (bookList.length === 1 ? ' disk' : ' disks');

    var xBox = document.getElementById('hub-extras'); xBox.innerHTML = '';
    CFG.extras.forEach(function(x){
      var found = posts.filter(function(q){ return has(q, x.label); });
      if (!found.length) return; /* show only extras that have posts */
      var card = el('a', 'extra');
      card.style.setProperty('--xc', x.color);
      if (found.length){
        card.href = found.length > 1 ? labelUrl(x.label) : found[0].url;
        if (x.label === 'Guide'){ var g = document.getElementById('hub-guide'); if (g) g.href = card.href; }
      }
      card.appendChild(el('div', 'extra-icon', x.icon));
      card.appendChild(el('div', 'extra-name', x.name));
      card.appendChild(el('div', 'extra-text', found.length ? x.text : 'Coming soon.'));
      xBox.appendChild(card);
    });
    if (!xBox.children.length){ xBox.style.display = 'none'; var xt = document.getElementById('hub-extras-title'); if (xt) xt.style.display = 'none'; }
  }

  /* ---------- Back to top ---------- */
  var top = document.getElementById('to-top');
  if (top){
    var tUpd = function(){ top.classList.toggle('show', window.scrollY > 600); };
    window.addEventListener('scroll', tUpd, { passive: true }); tUpd();
    top.addEventListener('click', function(){ window.scrollTo({ top: 0, behavior: reduce ? 'auto' : 'smooth' }); sfx('click'); });
  }
})();
//
